/* =====================================================================
   Agentic ODI — the site design system.

   Colours, radii, and easings live in assets/tokens.css, generated from
   the Living Studio's own theme so the site and the product are the same
   visual language. This file holds layout, type, components, and motion.

   Rule: no hex colour here. Everything is a var(--…) reference.
   ===================================================================== */

/* ---------------------------------------------------------------- */
/* Reset                                                            */
/* ---------------------------------------------------------------- */

*,
*::before,
*::after {
  box-sizing: border-box;
}

html {
  -webkit-text-size-adjust: 100%;
  scroll-behavior: smooth;
  scroll-padding-top: 96px;
}

body,
h1, h2, h3, h4, p, figure, blockquote, dl, dd, ul, ol {
  margin: 0;
}

ul[class], ol[class] {
  list-style: none;
  padding: 0;
}

img, svg, video {
  display: block;
  max-width: 100%;
}

button, input, select, textarea {
  font: inherit;
  color: inherit;
}

button {
  cursor: pointer;
  border: 0;
  background: none;
}

a {
  color: var(--accent);
  text-decoration: none;
}

a:hover {
  color: var(--text);
}

:focus-visible {
  outline: 2px solid var(--accent);
  outline-offset: 3px;
  border-radius: 4px;
}

::selection {
  background: var(--accent-strong);
  color: var(--text);
}

/* ---------------------------------------------------------------- */
/* Base                                                             */
/* ---------------------------------------------------------------- */

body {
  min-height: 100vh;
  background: var(--bg);
  color: var(--text);
  font-family: var(--font);
  font-size: 1.0625rem;
  line-height: 1.65;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
  overflow-x: hidden;
}

/* The canvas. The Studio's own two radial washes — depth without imagery. */
body::before {
  content: "";
  position: fixed;
  inset: 0;
  z-index: -1;
  pointer-events: none;
  background:
    radial-gradient(
      760px 420px at 50% 108%,
      color-mix(in srgb, var(--accent-strong) 9%, transparent),
      transparent 72%
    ),
    radial-gradient(
      900px 520px at 68% -12%,
      color-mix(in srgb, var(--accent-strong) 8%, transparent),
      transparent 68%
