  display: inline-flex;
  align-items: center;
  gap: 10px;
  color: var(--text);
}

.site-footer__tagline {
  color: var(--muted);
}

.site-footer__nav {
  display: flex;
  flex-wrap: wrap;
  gap: 8px 24px;
  margin-bottom: 28px;
}

.site-footer__nav a {
  color: var(--muted);
}

.site-footer__nav a:hover {
  color: var(--text);
}

.site-footer__legal {
  color: var(--faint);
}

.site-footer__note {
  margin-top: 6px;
  color: var(--faint);
}

/* ---------------------------------------------------------------- */
/* Buttons, pills, cards                                            */
/* ---------------------------------------------------------------- */

.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  padding: 13px 24px;
  border: 1px solid transparent;
  border-radius: var(--r-pill);
  font-size: 0.9375rem;
  font-weight: 600;
  letter-spacing: -0.01em;
  transition:
    transform 0.15s var(--ease-tactile),
    background-color 0.15s var(--ease-tactile),
    border-color 0.15s var(--ease-tactile),
    opacity 0.15s var(--ease-tactile);
}

.btn--primary {
  background: var(--accent);
  color: var(--accent-ink);
}

.btn--primary:hover {
  color: var(--accent-ink);
  transform: translateY(-1px);
  opacity: 0.92;
}

.btn--ghost {
  border-color: var(--line-strong);
  background: var(--surface);
  color: var(--text);
}

.btn--ghost:hover {
  color: var(--text);
  transform: translateY(-1px);
  background: var(--surface-hover);
}

.btn--sm {
  padding: 9px 18px;
  font-size: 0.875rem;
}

.btn:active {
  transform: scale(0.98);
}

.pill {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 3px 10px;
  border: 1px solid var(--line-strong);
  border-radius: var(--r-pill);
  font-size: 0.6875rem;
  font-weight: 600;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  color: var(--muted);
  white-space: nowrap;
}

.pill--accent {
  border-color: color-mix(in srgb, var(--accent) 34%, transparent);
  background: color-mix(in srgb, var(--accent) 12%, transparent);
  color: var(--accent);
}

.pill--positive {
  border-color: color-mix(in srgb, var(--green) 28%, transparent);
  background: color-mix(in srgb, var(--green) 10%, transparent);
  color: var(--green);
}

.pill--warning {
  border-color: color-mix(in srgb, var(--amber) 30%, transparent);
  background: color-mix(in srgb, var(--amber) 10%, transparent);
  color: var(--amber);
}

.card {
  padding: 24px;
  border: 1px solid var(--line);
  border-radius: var(--r-lg);
  background: var(--surface);
  transition:
    transform 0.2s var(--ease-apple-out),
    border-color 0.2s var(--ease-apple-out),
    background-color 0.2s var(--ease-apple-out);
}

.card:hover {
  transform: translateY(-2px);
  border-color: var(--line-strong);
  background: var(--surface-hover);
}

.card__title {
  font-size: 1.0625rem;
  font-weight: 600;
  letter-spacing: -0.01em;
}

.card__body {
  margin-top: 10px;
  color: var(--muted);
  font-size: 0.9375rem;
  line-height: 1.6;
}

.glass {
  border: 1px solid var(--line-strong);
  border-radius: var(--r-lg);
  background: var(--glass);
  backdrop-filter: var(--glass-blur);
  -webkit-backdrop-filter: var(--glass-blur);
  box-shadow: var(--hairline), 0 40px 120px -20px rgba(0, 0, 0, 0.85);
}

/* ---------------------------------------------------------------- */
/* Hero                                                             */
/* ---------------------------------------------------------------- */

.hero {
  display: flex;
  align-items: center;
  min-height: calc(100svh - 68px);
  padding-block: clamp(72px, 11vw, 140px);
  text-align: center;
}

.hero__inner {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 24px;
}

.hero__title {
  max-width: 16ch;
  font-size: clamp(2.75rem, 7.5vw, 6rem);
  font-weight: 600;
  letter-spacing: -0.04em;
  line-height: 0.98;
}

.hero__sub {
  max-width: 46ch;
  color: var(--muted);
  font-size: clamp(1.0625rem, 1.6vw, 1.375rem);
  line-height: 1.5;
}

.hero__actions {
  display: flex;
  flex-wrap: wrap;
  justify-content: center;
  gap: 12px;
  margin-top: 8px;
}

.hero__cue {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  margin-top: 12px;
  color: var(--faint);
  font-size: 0.8125rem;
}

.hero__cue span {
  display: block;
  width: 1px;
  height: 22px;
  background: linear-gradient(to bottom, var(--line-strong), transparent);
}

/* ---------------------------------------------------------------- */
/* Problem                                                          */
/* ---------------------------------------------------------------- */

.beats {
  display: grid;
  gap: 20px;
  grid-template-columns: repeat(auto-fit, minmax(260px, 1fr));
}

.beat {
  display: flex;
  flex-direction: column;
  gap: 12px;
  padding: 26px;
  border: 1px solid var(--line);
  border-radius: var(--r-lg);
  background: var(--surface);
}

.beat__quote {
  font-size: 1.125rem;
  font-weight: 600;
  letter-spacing: -0.01em;
  line-height: 1.35;
}

.beat__support {
  color: var(--muted);
  font-size: 0.9375rem;
  line-height: 1.6;
}

.closer {
  margin-top: 40px;
  max-width: 34ch;
  font-size: clamp(1.375rem, 2.4vw, 2rem);
  font-weight: 600;
  letter-spacing: -0.025em;
  line-height: 1.2;
  color: var(--text);
}

/* ---------------------------------------------------------------- */
/* Insight — the formula                                            */
/* ---------------------------------------------------------------- */

.insight {
  display: grid;
  gap: clamp(40px, 6vw, 72px);
  grid-template-columns: minmax(0, 1fr);
  align-items: start;
}

@media (min-width: 960px) {
  .insight {
    grid-template-columns: minmax(0, 1fr) minmax(0, 1fr);
  }
}

.formula {
  display: flex;
  flex-wrap: wrap;
  align-items: baseline;
  gap: 10px;
  padding: 22px 24px;
  border: 1px solid var(--line);
  border-radius: var(--r-md);
  background: var(--bg-sunken);
  font-family: var(--mono);
  font-size: clamp(0.9375rem, 1.6vw, 1.125rem);
  line-height: 1.5;
}

.formula__label {
  color: var(--muted);
}

.formula__expr {
  color: var(--text);
}

.formula__gap {
  color: var(--accent);
}

.statline {
  display: flex;
  flex-wrap: wrap;
  align-items: baseline;
  gap: 8px 12px;
  margin-top: 20px;
  font-size: 0.9375rem;
}

.statline__value {
  font-size: 1.125rem;
  font-weight: 600;
  letter-spacing: -0.01em;
}

.statline__source {
  color: var(--faint);
}

/* The importance/satisfaction gap, drawn honestly. */
.gap {
  display: flex;
  flex-direction: column;
  gap: 14px;
  padding: 24px;
  border: 1px solid var(--line);
  border-radius: var(--r-lg);
  background: var(--surface);
}

.gap__row {
  display: grid;
  grid-template-columns: 96px 1fr 40px;
  align-items: center;
  gap: 14px;
  font-size: 0.8125rem;
  color: var(--muted);
}

.gap__track {
  height: 8px;
  border-radius: var(--r-pill);
  background: var(--surface-hover);
  overflow: hidden;
}

.gap__fill {
  height: 100%;
  border-radius: var(--r-pill);
  background: var(--accent-strong);
}

.gap__fill--satisfaction {
  background: color-mix(in srgb, var(--muted) 55%, transparent);
}

.gap__value {
  font-family: var(--mono);
  font-size: 0.8125rem;
  text-align: right;
  color: var(--text);
}

.gap__note {
  color: var(--faint);
  font-size: 0.8125rem;
  line-height: 1.5;
}

/* ---------------------------------------------------------------- */
/* Surfaces — the six catalog cards                                  */
/* ---------------------------------------------------------------- */

.surface {
  display: flex;
  flex-direction: column;
  gap: 14px;
  padding: 22px;
  border: 1px solid var(--line);
  border-radius: var(--r-md);
  background: var(--bg-raised);
  box-shadow: var(--hairline);
}

.surface__head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
}

.surface__id {
  font-family: var(--mono);
  font-size: 0.6875rem;
  font-weight: 600;
  letter-spacing: 0.09em;
  text-transform: uppercase;
  color: var(--accent);
}

.surface__statement {
  font-size: 0.9375rem;
  font-weight: 500;
  line-height: 1.5;
}

.surface__meta {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
}

.surface__scores {
  display: flex;
  align-items: baseline;
  gap: 10px;
  font-family: var(--mono);
  font-size: 0.8125rem;
  color: var(--muted);
}

.surface__opportunity {
  font-size: 1.375rem;
  font-weight: 600;
  letter-spacing: -0.02em;
  color: var(--text);
}

.meter {
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.meter__head {
  display: flex;
  justify-content: space-between;
  font-size: 0.6875rem;
  letter-spacing: 0.07em;
  text-transform: uppercase;
  color: var(--faint);
}

.meter__track {
  height: 6px;
  border-radius: var(--r-pill);
  background: var(--surface-hover);
  overflow: hidden;
}

.meter__fill {
  height: 100%;
  border-radius: var(--r-pill);
  background: var(--accent);
}

.meter__fill--positive { background: var(--green); }
.meter__fill--warning { background: var(--amber); }

.jobmap {
  display: flex;
  flex-direction: column;
  gap: 6px;
  margin: 0;
  padding: 0;
  list-style: none;
}

.jobmap__step {
  display: flex;
  align-items: baseline;
  gap: 10px;
  padding: 9px 12px;
  border-left: 2px solid color-mix(in srgb, var(--accent) 50%, transparent);
  border-radius: 0 var(--r-sm) var(--r-sm) 0;
  background: var(--surface);
  font-size: 0.875rem;
}

.jobmap__index {
  font-family: var(--mono);
  font-size: 0.6875rem;
  color: var(--accent);
}

.compare {
  display: grid;
  gap: 8px;
  grid-template-columns: 1fr 1fr;
}

.compare__col {
  padding: 12px;
  border: 1px solid var(--line);
  border-radius: var(--r-md);
  font-size: 0.8125rem;
  line-height: 1.5;
}

.compare__col--after {
  border-color: color-mix(in srgb, var(--green) 22%, transparent);
  background: color-mix(in srgb, var(--green) 6%, transparent);
}

.compare__col--before {
  border-color: color-mix(in srgb, var(--red) 20%, transparent);
  background: color-mix(in srgb, var(--red) 6%, transparent);
}

.compare__label {
  display: block;
  margin-bottom: 6px;
  font-size: 0.6875rem;
  font-weight: 600;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  color: var(--faint);
}

.evidence {
  padding: 12px 14px;
  border-left: 2px solid color-mix(in srgb, var(--accent) 50%, transparent);
  border-radius: 0 var(--r-sm) var(--r-sm) 0;
  background: var(--surface);
}

.evidence__quote {
  color: var(--text);
  font-size: 0.875rem;
  font-style: italic;
  line-height: 1.55;
}

.evidence__meta {
  display: block;
  margin-top: 8px;
  color: var(--faint);
  font-size: 0.6875rem;
}

/* ---------------------------------------------------------------- */
/* Steps                                                            */
/* ---------------------------------------------------------------- */

.steps {
  display: grid;
  gap: 20px;
  grid-template-columns: repeat(auto-fit, minmax(260px, 1fr));
  counter-reset: step;
}

.step {
  position: relative;
  display: flex;
  flex-direction: column;
  gap: 12px;
  padding: 26px;
  border: 1px solid var(--line);
  border-radius: var(--r-lg);
  background: var(--surface);
  counter-increment: step;
}

.step::before {
  content: counter(step, decimal-leading-zero);
  font-family: var(--mono);
  font-size: 0.6875rem;
  font-weight: 600;
  letter-spacing: 0.1em;
  color: var(--accent);
}

.step__title {
  font-size: 1.125rem;
  font-weight: 600;
  letter-spacing: -0.01em;
}

.step__body {
  color: var(--muted);
  font-size: 0.9375rem;
  line-height: 1.6;
}

/* ---------------------------------------------------------------- */
/* Connectors                                                       */
/* ---------------------------------------------------------------- */

.connector-group + .connector-group {
  margin-top: 36px;
}

.connector-list {
  display: grid;
  gap: 12px;
  grid-template-columns: repeat(auto-fit, minmax(280px, 1fr));
}

.connector {
  display: flex;
  flex-direction: column;
  gap: 8px;
  padding: 18px 20px;
  border: 1px solid var(--line);
  border-radius: var(--r-md);
  background: var(--surface);
  transition:
    transform 0.18s var(--ease-apple-out),
    border-color 0.18s var(--ease-apple-out);
}

.connector:hover {
  transform: translateY(-2px);
  border-color: var(--line-strong);
}

.connector__head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
}

.connector__name {
  font-size: 0.9375rem;
  font-weight: 600;
}

.connector__summary {
  color: var(--muted);
  font-size: 0.8125rem;
  line-height: 1.55;
}

.connector__env {
  font-family: var(--mono);
  font-size: 0.6875rem;
  color: var(--faint);
}

/* ---------------------------------------------------------------- */
/* Code                                                             */
/* ---------------------------------------------------------------- */

.codeblock {
  position: relative;
  margin: 0;
  padding: 20px 22px;
  border: 1px solid var(--line);
  border-radius: var(--r-md);
  background: var(--bg-sunken);
  overflow-x: auto;
  font-family: var(--mono);
  font-size: 0.875rem;
  line-height: 1.65;
  color: var(--text);
  tab-size: 2;
}

.codeblock code {
  font-family: var(--mono);
}

.copy-btn {
  position: absolute;
  top: 10px;
  right: 10px;
  padding: 5px 12px;
  border: 1px solid var(--line-strong);
  border-radius: var(--r-pill);
  background: var(--bg-raised);
  color: var(--muted);
  font-family: var(--font);
  font-size: 0.75rem;
  font-weight: 600;
  opacity: 0;
  transition:
    opacity 0.15s var(--ease-tactile),
    color 0.15s var(--ease-tactile),
    border-color 0.15s var(--ease-tactile);
}

.codeblock:hover .copy-btn,
.copy-btn:focus-visible {
  opacity: 1;
}

.copy-btn:hover {
  color: var(--text);
  border-color: var(--line-strong);
}

/* Syntax highlighting, server-rendered by Pygments. */
.highlight {
  margin: 0;
  padding: 20px 22px;
  border: 1px solid var(--line);
  border-radius: var(--r-md);
  background: var(--bg-sunken);
  overflow-x: auto;
  font-family: var(--mono);
  font-size: 0.875rem;
  line-height: 1.65;
}

.highlight pre {
  margin: 0;
  font-family: var(--mono);
}

.highlight code {
  font-family: var(--mono);
}

/* ---------------------------------------------------------------- */
/* Tabs                                                             */
/* ---------------------------------------------------------------- */

.tabs__list {
  display: inline-flex;
  gap: 4px;
  padding: 4px;
  border: 1px solid var(--line);
  border-radius: var(--r-pill);
  background: var(--surface);
}

.tabs__tab {
  padding: 8px 18px;
  border-radius: var(--r-pill);
  font-size: 0.875rem;
  font-weight: 500;
  color: var(--muted);
  transition:
    background-color 0.15s var(--ease-tactile),
    color 0.15s var(--ease-tactile);
}

.tabs__tab[aria-selected="true"] {
  background: var(--surface-hover);
  color: var(--text);
}

.tabs__panel {
  margin-top: 20px;
}

.tabs__panel[hidden] {
  display: none;
}

/* ---------------------------------------------------------------- */
/* Endpoints                                                        */
/* ---------------------------------------------------------------- */

.endpoints {
  display: flex;
  flex-direction: column;
  gap: 0;
  border: 1px solid var(--line);
  border-radius: var(--r-md);
  overflow: hidden;
}

.endpoint {
  display: grid;
  gap: 4px 20px;
  grid-template-columns: minmax(0, 1fr);
  padding: 18px 22px;
  background: var(--surface);
}

.endpoint + .endpoint {
  border-top: 1px solid var(--line);
}

@media (min-width: 760px) {
  .endpoint {
    grid-template-columns: 200px minmax(0, 1fr);
    align-items: center;
  }
}

.endpoint__name {
  font-size: 0.875rem;
  font-weight: 600;
}

.endpoint__url {
  display: flex;
  align-items: center;
  gap: 10px;
  font-family: var(--mono);
  font-size: 0.8125rem;
  color: var(--muted);
  overflow-wrap: anywhere;
}

.endpoint__note {
  grid-column: 1 / -1;
  color: var(--faint);
  font-size: 0.8125rem;
  line-height: 1.5;
}

/* ---------------------------------------------------------------- */
/* Tools preview                                                    */
/* ---------------------------------------------------------------- */

.tool {
  display: flex;
  flex-direction: column;
  gap: 8px;
  padding: 18px 20px;
  border: 1px solid var(--line);
  border-radius: var(--r-md);
  background: var(--surface);
}

.tool__name {
  font-family: var(--mono);
  font-size: 0.875rem;
  font-weight: 600;
  color: var(--accent);
}

.tool__purpose {
  color: var(--muted);
  font-size: 0.875rem;
  line-height: 1.55;
}

.tool__sig {
  font-family: var(--mono);
  font-size: 0.75rem;
  color: var(--faint);
  overflow-wrap: anywhere;
}

/* ---------------------------------------------------------------- */
/* Status                                                           */
/* ---------------------------------------------------------------- */

.status-grid {
  display: grid;
  gap: 20px;
  grid-template-columns: repeat(auto-fit, minmax(280px, 1fr));
}

.status-list {
  display: flex;
  flex-direction: column;
  gap: 12px;
  margin: 0;
  padding: 0;
  list-style: none;
}

.status-list li {
  display: flex;
  align-items: baseline;
  gap: 10px;
  color: var(--muted);
  font-size: 0.9375rem;
  line-height: 1.55;
}

.status-list li::before {
  content: "";
  flex: none;
  width: 5px;
  height: 5px;
  margin-top: 9px;
  border-radius: 50%;
  background: var(--accent);
}

.status-note {
  margin-top: 40px;
  font-size: 1.125rem;
  font-weight: 600;
  letter-spacing: -0.01em;
}

/* ---------------------------------------------------------------- */
/* Motion                                                           */
/* ---------------------------------------------------------------- */

@keyframes hero-in {
  from {
    opacity: 0;
    transform: translateY(10px);
    filter: blur(4px);
  }
  to {
    opacity: 1;
    transform: none;
    filter: blur(0);
  }
}

@keyframes reveal-up {
  from {
    opacity: 0;
    transform: translateY(24px);
  }
  to {
    opacity: 1;
    transform: none;
  }
}

@keyframes surface-in {
  from {
    opacity: 0;
    transform: translateY(10px) scale(0.985);
  }
  to {
    opacity: 1;
    transform: none;
  }
}

@keyframes caret-blink {
  0%, 45% { opacity: 1; }
  46%, 100% { opacity: 0; }
}

.hero__eyebrow { animation: hero-in 0.7s var(--ease-apple-out) both; }
.hero__title    { animation: hero-in 0.7s var(--ease-apple-out) 0.09s both; }
.hero__sub      { animation: hero-in 0.7s var(--ease-apple-out) 0.18s both; }
.hero__actions  { animation: hero-in 0.7s var(--ease-apple-out) 0.27s both; }
.hero__cue      { animation: hero-in 0.7s var(--ease-apple-out) 0.36s both; }

/* Reveal-on-scroll. Content is visible by default; the observer opts it
   into the hidden state only after it loads, so no-JS readers never lose
   anything. */
.js-reveal [data-reveal] {
  opacity: 0;
  transform: translateY(24px);
  transition:
    opacity 0.8s var(--ease-apple-out),
    transform 0.8s var(--ease-apple-out);
}

.js-reveal [data-reveal].is-visible {
  opacity: 1;
  transform: none;
}

@media (prefers-reduced-motion: reduce) {
  html {
    scroll-behavior: auto;
  }

  *,
  *::before,
  *::after {
    animation-duration: 0.001ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.001ms !important;
    scroll-behavior: auto !important;
  }

  .js-reveal [data-reveal] {
    opacity: 1;
    transform: none;
  }
}

/* ---------------------------------------------------------------- */
/* Responsive                                                       */
/* ---------------------------------------------------------------- */

@media (max-width: 860px) {
  .site-nav {
    display: none;
  }
}

@media (max-width: 640px) {
  .compare {
    grid-template-columns: 1fr;
  }

  .gap__row {
    grid-template-columns: 78px 1fr 34px;
    gap: 10px;
  }
}

